const { state, setState, resetState } = useProState({ page: 1, keyword: '' }, { autoMergeObject: true })

setState({ keyword: '\u641C\u7D22\u8BCD' })
// \u7ED3\u679C\uFF1A{ page: 1, keyword: '\u641C\u7D22\u8BCD' }\uFF08\u81EA\u52A8\u5408\u5E76\uFF0C\u65E0\u9700\u5C55\u5F00\uFF09

setState((prev) => ({ page: prev.page + 1 }))

resetState()
// \u6062\u590D\u4E3A { page: 1, keyword: '' }
