import { useI18n } from '@fexd/pro-components'

function MyComponent() {
  const { t, jsxT } = useI18n()
  // \u6216\u4F7F\u7528\u522B\u540D
  // const { t, jsxT } = useTranslation()

  return (
    <div>
      <h1>{t('utils.confirm')}</h1>
      {/* jsxT \u5185\u90E8\u4F7F\u7528 '@type': 'jsx' */}
      <p>{jsxT('greeting.welcome', { name: <strong>\u5F20\u4E09</strong> })}</p>
    </div>
  )
}
