// 1. \u521B\u5EFA fallback \u5B9E\u4F8B\uFF08\u5E95\u5C42\uFF09
const globalI18n = new I18n({
  types: {
    default: {
      resources: {
        zh_CN: { utils: { confirm: '\u786E\u8BA4', cancel: '\u53D6\u6D88' } },
      },
    },
  },
})

// 2. \u521B\u5EFA\u5E26 fallback \u7684\u5B9E\u4F8B\uFF08\u4E0A\u5C42\uFF09
const scopeI18n = new I18n({
  fallback: [globalI18n],  // \u8BBE\u7F6E fallback \u94FE
  types: {
    default: {
      resources: {
        zh_CN: {
          // \u53EA\u6709 greeting\uFF0C\u6CA1\u6709 utils
          greeting: '\u4F60\u597D',
        },
      },
    },
  },
})

// await I18n.applyLanguage('zh_CN')

// scopeI18n \u6709\u81EA\u5DF1\u7684 greeting
scopeI18n.t('greeting')  // \u2192 '\u4F60\u597D'

// scopeI18n \u6CA1\u6709 utils.confirm\uFF0Cfallback \u5230 globalI18n
scopeI18n.t('utils.confirm')  // \u2192 '\u786E\u8BA4'

// \u4E24\u4E2A\u5B9E\u4F8B\u90FD\u6CA1\u6709\u7684 key\uFF0C\u8FD4\u56DE key \u672C\u8EAB
scopeI18n.t('nonexistent.key')  // \u2192 'nonexistent.key'
`,paraId:102,tocIndex:57},{value:`// packages/table/src/plugins/config/useLocales.tsx
