import { dayjsTZ } from '@fexd/pro-components'
import { Card, Select, Space, Typography, Divider } from 'antd'

const { Text } = Typography

const timezoneOptions = [
  { label: '\u{1F1E8}\u{1F1F3} \u4E0A\u6D77 (UTC+8)', value: 'Asia/Shanghai' },
  { label: '\u{1F1EE}\u{1F1E9} \u96C5\u52A0\u8FBE (UTC+7)', value: 'Asia/Jakarta' },
  { label: '\u{1F1FA}\u{1F1F8} \u7EBD\u7EA6 (UTC-5)', value: 'America/New_York' },
  { label: '\u{1F1EC}\u{1F1E7} \u4F26\u6566 (UTC+0)', value: 'Europe/London' },
  { label: '\u{1F1EF}\u{1F1F5} \u4E1C\u4EAC (UTC+9)', value: 'Asia/Tokyo' },
  { label: '\u{1F1E6}\u{1F1FA} \u6089\u5C3C (UTC+10)', value: 'Australia/Sydney' },
]

const locales = [
  { key: 'zh-cn', label: '\u4E2D\u6587' },
  { key: 'en', label: 'English' },
  { key: 'id', label: 'Indonesia' },
]

export default () => {
  const [timezone, setTimezone] = useState('Asia/Shanghai')
  const [, forceUpdate] = useState(0)

  const now = new Date()
  const localFormatted = dayjsTZ(now).format('YYYY-MM-DD HH:mm:ss')
  const tzFormatted = dayjsTZ(now).tz(timezone).format('YYYY-MM-DD HH:mm:ss')
  const threeDaysAgo = dayjsTZ(now).subtract(3, 'day')

  return (
    <Card size="small" title="dayjsTZ \u65F6\u533A\u6F14\u793A">
      <Space direction="vertical" style={{ width: '100%' }}>
        <Space>
          <Text type="secondary">\u9009\u62E9\u65F6\u533A\uFF1A</Text>
          <Select
            value={timezone}
            onChange={(v) => {
              setTimezone(v)
              forceUpdate((n) => n + 1)
            }}
            options={timezoneOptions}
            style={{ width: 240 }}
          />
        </Space>

        <Divider style={{ margin: '8px 0' }} />

        <div>
          <Text strong>\u672C\u5730\u65F6\u95F4\uFF1A</Text>
          <Text code>{localFormatted}</Text>
        </div>
        <div>
          <Text strong>{timezone}\uFF1A</Text>
          <Text code>{tzFormatted}</Text>
        </div>

        <Divider style={{ margin: '8px 0' }} />

        <Text type="secondary">\u76F8\u5BF9\u65F6\u95F4\uFF08\u591A\u8BED\u8A00\uFF09\uFF1A</Text>
        {locales.map(({ key, label }) => (
          <div key={key} style={{ marginBottom: 2 }}>
            <Text style={{ display: 'inline-block', width: 80 }}>{label}:</Text>
            <Text code>{threeDaysAgo.locale(key).fromNow()}</Text>
          </div>
        ))}
      </Space>
    </Card>
  )
}
